mapper.select:
SELECT DAT_ZIP_CODE,SUM(aNum) aNum FROM ( SELECT DAT_ZIP_CODE,COUNT(1) aNum FROM PBC_PRD_BASEINFO_SUB_DAT WHERE 1=1 and SEND_STATUS IN ('02','03')
#{item,jdbcType=VARCHAR}
group by DAT_ZIP_CODE UNION ALL SELECT DAT_ZIP_CODE,COUNT(1) aNum FROM PBC_PRD_BASEINFO_END_SUB_DAT WHERE 1=1 and SEND_STATUS IN ('02','03')
#{item,jdbcType=VARCHAR}
group by DAT_ZIP_CODE) group by DAT_ZIP_CODE

mapper.update:
UPDATE PBC_SEND_ZIP_DAT_FILE F SET PIB_DETAIL_CNT = ( select aNum from (SELECT DAT_ZIP_CODE,SUM(nvl(aNum,0)) aNum FROM ( SELECT DAT_ZIP_CODE,COUNT(1) aNum FROM PBC_PRD_BASEINFO_SUB_DAT WHERE 1=1 and SEND_STATUS IN ('02','03')
#{item,jdbcType=VARCHAR}
group by DAT_ZIP_CODE UNION ALL SELECT DAT_ZIP_CODE,COUNT(1) aNum FROM PBC_PRD_BASEINFO_END_SUB_DAT WHERE 1=1 and SEND_STATUS IN ('02','03')
#{item,jdbcType=VARCHAR}
group by DAT_ZIP_CODE) group by DAT_ZIP_CODE) d where d.DAT_ZIP_CODE = f.DAT_ZIP_CODE) WHERE DAT_ZIP_TYPE = 'PI' AND ZIP_SEND_STATUS = '01'
and ORG_CODE = #{OrgCode,jdbcType=VARCHAR}

